package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
public class RootCaptureScopeTest {
 @Test public void independentRolesAndNoPreflightSecond(){assertTrue(RootCaptureScope.allowed(RootCaptureScope.Mode.PREFLIGHT,RootCaptureScope.Phase.FIRST));assertFalse(RootCaptureScope.allowed(RootCaptureScope.Mode.PREFLIGHT,RootCaptureScope.Phase.SECOND));assertTrue(RootCaptureScope.allowed(RootCaptureScope.Mode.BUSINESS,RootCaptureScope.Phase.SECOND));assertFalse(RootCaptureScope.allowed(null,RootCaptureScope.Phase.FIRST));assertFalse(RootCaptureScope.allowed(RootCaptureScope.Mode.BUSINESS,null));}
 @Test public void disjointNamespaceAndOneClaimPerBusinessPhase(){assertEquals("rewards-root-family-preflight-20261111-v27",RootCaptureScope.directory(RootCaptureScope.Mode.PREFLIGHT));assertEquals(AutonomousRewardCardScope.DIRECTORY,RootCaptureScope.directory(RootCaptureScope.Mode.BUSINESS));assertNotEquals(RootCaptureScope.directory(RootCaptureScope.Mode.PREFLIGHT),RootCaptureScope.directory(RootCaptureScope.Mode.BUSINESS));assertEquals("BEFORE",RootCaptureScope.slot(RootCaptureScope.Mode.BUSINESS,RootCaptureScope.Phase.FIRST));assertEquals("AFTER",RootCaptureScope.slot(RootCaptureScope.Mode.BUSINESS,RootCaptureScope.Phase.SECOND));assertThrows(SecurityException.class,()->RootCaptureScope.slot(RootCaptureScope.Mode.PREFLIGHT,RootCaptureScope.Phase.SECOND));}
 @Test public void halfOpenAndAdmissionMargin(){long s=RootCaptureScope.STARTS_UTC,e=RootCaptureScope.EXPIRES_UTC;assertFalse(RootCaptureScope.current(s-1));assertTrue(RootCaptureScope.current(s));assertTrue(RootCaptureScope.current(e-1));assertFalse(RootCaptureScope.current(e));assertTrue(RootCaptureScope.admissionCurrent(e-90001));assertFalse(RootCaptureScope.admissionCurrent(e-90000));}
 @Test public void finiteSessionAndPhaseDoNotExtend(){long u=RootCaptureScope.STARTS_UTC;assertEquals(190000,RootCaptureScope.sessionDeadline(10000,u));assertEquals(100000,RootCaptureScope.deadline(10000,u,190000));assertEquals(11000,RootCaptureScope.deadline(10000,u,11000));assertEquals(100001,RootCaptureScope.sessionDeadline(10000,RootCaptureScope.EXPIRES_UTC-90001));}
 @Test public void badTimeAndExpiredReject(){long u=RootCaptureScope.STARTS_UTC;assertThrows(SecurityException.class,()->RootCaptureScope.sessionDeadline(-1,u));assertThrows(SecurityException.class,()->RootCaptureScope.sessionDeadline(Long.MAX_VALUE,u));assertThrows(SecurityException.class,()->RootCaptureScope.deadline(1,u,1));assertThrows(SecurityException.class,()->RootCaptureScope.deadline(1,RootCaptureScope.EXPIRES_UTC,100));}
 @Test public void businessScopeSameWindow(){assertEquals(AutonomousRewardCardScope.STARTS_UTC,RootCaptureScope.STARTS_UTC);assertEquals(AutonomousRewardCardScope.EXPIRES_UTC,RootCaptureScope.EXPIRES_UTC);assertEquals(AutonomousRewardCardScope.SESSION_TTL,RootCaptureScope.SESSION_TTL);assertEquals(AutonomousRewardCardScope.CAPTURE_TTL,RootCaptureScope.CAPTURE_TTL);}
}
